import { html, render } from "lit-html";
import * as QRCode from "qrcode";
import query from "query-string";
import { DEFAULT_SERVER_URL, MatchmakingClient } from "../matchmaking/client";
import { PeerConnection } from "../matchmaking/peerconnection";
import { Disposable, TypedEvent } from "../matchmaking/typedevent";
import { NetplayPlayer, RemotePlayer } from "../netcode/types";
import { Data } from "../types";

type PendingRemotePlayer = {
  id: string;
  isLocal: false;
};

type GameMenuState =
  | {
      kind: "connecting-to-server";
    }
  | {
      kind: "player-count-selection";
    }
  | {
      kind: "registered";
      clientID: string;
      joinURL: string;
      qrCanvas: HTMLCanvasElement;
      playerCount: number;
      players: (PendingRemotePlayer | NetplayPlayer)[];
    }
  | {
      kind: "connecting-to-peers";
      hostID: string;
      playerCount: number;
    }
  | {
      kind: "searching-for-matches";
      playerCount: number;
    }
  | {
      kind: "hosting-public-match";
      playerCount: number;
      players: (PendingRemotePlayer | NetplayPlayer)[];
    }
  | {
      kind: "game-in-progress";
    }
  | {
      kind: "connection-closed";
    };

export class GameMenu {
  root: HTMLDivElement;

  state: GameMenuState = { kind: "connecting-to-server" };

  matchmaker: MatchmakingClient;

  gameURL: string;

  onGameStart: TypedEvent<{ players: NetplayPlayer[]; roomId: string }> =
    new TypedEvent();

  private playerCount: number = 2;
  private connections: Map<string, PeerConnection> = new Map();
  private readyClients: Set<string> = new Set();

  selectPlayerCount(count: number) {
    this.playerCount = count;
    this.readyClients.clear();
    const room = this.matchmaker.clientID!;
    const joinURL = this.getJoinURL(room, count);

    const qrCanvas = document.createElement("canvas");
    QRCode.toCanvas(qrCanvas, joinURL);

    this.updateState({
      kind: "registered",
      clientID: room,
      joinURL: joinURL,
      qrCanvas,
      playerCount: count,
      players: [{ id: this.matchmaker.clientID!, isLocal: true }],
    });

    this.startHostListening();
  }

  async connectToPeers(hostID: string, playerCount: number) {
    this.updateState({
      kind: "connecting-to-peers",
      hostID,
      playerCount,
    });

    // Listen for incoming connections from other peers
    this.matchmaker.onConnection.on((conn) => {
      // Don't handle host connection here (handled separately below)
      if (conn.peerID !== hostID) {
        console.log(`Received connection from ${conn.peerID}`);
        this.connections.set(conn.peerID, conn);
      }
    });

    // First connect to host
    const hostConn = this.matchmaker.connectPeer(hostID);
    this.connections.set(hostID, hostConn);

    hostConn.on("open", () => {
      // Request peer list from host
      hostConn.send({
        type: "request-peer-list",
        clientID: this.matchmaker.clientID!,
      });
    });

    hostConn.on("data", async (data: Data) => {
      if (data.type === "peer-list") {
        console.log("Received peer list from", hostID, data.peers);
        // Connect to all other peers
        const otherPeers = data.peers.filter(
          (p: string) => p !== this.matchmaker.clientID! && p !== hostID
        );

        for (const peerID of otherPeers) {
          // Only initiate connection if our ID is lexicographically smaller
          // This prevents both peers from trying to initiate simultaneously
          if (this.matchmaker.clientID! < peerID) {
            console.log(`Initiating connection to ${peerID}`);
            const conn = this.matchmaker.connectPeer(peerID);
            this.connections.set(peerID, conn);
          } else {
            console.log(`Waiting for connection from ${peerID}`);
          }
        }

        // Wait for all connections to open (both initiated and received)
        await this.waitForAllConnections();
        
        // Notify host that we're ready
        console.log("All connections established, sending ready signal to host");
        hostConn.send({
          type: "client-ready",
          clientID: this.matchmaker.clientID!,
        });
      } else if (data.type === "start-game") {
        // Start the game when host tells us to
        this.startGame(data.roomId);
      }
    });

    hostConn.onClose.on(() => {
      this.updateState({
        kind: "connection-closed",
      });
    });
  }

  constructor() {
    // Set the root DIV element.
    this.root = this.createRootElement();

    // The URL of the game is everything before the hash.
    this.gameURL = window.location.href.split("#")[0];

    // Parse the window hash for params.
    const parsedHash = query.parse(window.location.hash);

    // Determine the server URL to connect to.
    const serverURL: string =
      (parsedHash.server as string) ||
      this.getLocalStorageServerOverride() ||
      DEFAULT_SERVER_URL;

    // Create a matchmaking client and connect to the server.
    this.matchmaker = new MatchmakingClient(serverURL);

    // Wait for the client to be registered.
    this.matchmaker.onRegistered.once(() => {
      if (parsedHash.room) {
        // If a hostID was provided in the URL hash,
        // get player count from hash or default to 2
        const hostID = parsedHash.room as string;
        const playerCount = parsedHash.players
          ? parseInt(parsedHash.players as string)
          : 2;
        this.playerCount = playerCount;
        this.connectToPeers(hostID, playerCount);
      } else {
        // Show player count selection
        this.updateState({
          kind: "player-count-selection",
        });
      }
    });

    this.render();
  }

  hostListeningHandle?: Disposable;
  startHostListening() {
    console.log("Starting host listening", this.state);
    this.hostListeningHandle = this.matchmaker.onConnection.on((conn) => {
      conn.on("open", () => {
        this.connections.set(conn.peerID, conn);

        if (
          this.state.kind === "registered" ||
          this.state.kind === "hosting-public-match"
        ) {
          const players = this.state.players.map(
            (player: PendingRemotePlayer | NetplayPlayer) =>
              player.id === conn.peerID ? { ...player, conn } : player
          );

          this.updateState({
            ...this.state,
            players,
          });

          // Handle peer list requests and ready signals
          conn.on("data", (data: Data) => {
            if (data.type === "request-peer-list") {
              // Send list of all connected peers
              console.log("Sending peer list to", conn.peerID);
              const peerIDs = players.map((p) => String(p.id));
              conn.send({
                type: "peer-list",
                peers: peerIDs,
                roomId: this.matchmaker.clientID!, // Host's ID is the room ID
              });
            } else if (data.type === "client-ready") {
              // Mark this client as ready
              console.log("Client ready:", data.clientID);
              this.readyClients.add(data.clientID);
              
              // Check if all clients are ready
              this.checkAndStartGame();
            }
          });

          const connectedPlayers = players.filter(
            (p) => p.isLocal === true || (p as RemotePlayer).conn !== undefined
          );

          // Check if we have enough players connected to host
          if (connectedPlayers.length === this.playerCount) {
            // Wait for all clients to be ready (connected to each other)
            this.checkAndStartGame();
          }
        }

        conn.onClose.on(() => {
          // Remove disconnected player
          this.connections.delete(conn.peerID);
          if (
            this.state.kind === "registered" ||
            this.state.kind === "hosting-public-match"
          ) {
            const players = this.state.players.filter(
              (p) => p.id !== conn.peerID
            );
            this.updateState({
              ...this.state,
              players,
            });
          }
        });
      });
    });
  }

  stopHostListening() {
    this.hostListeningHandle!.dispose();
  }

  async waitForAllConnections(): Promise<void> {
    const promises = Array.from(this.connections.values()).map((conn) => {
      return new Promise<void>((resolve) => {
        if (conn.dataChannel?.readyState === "open") {
          resolve();
        } else {
          conn.on("open", () => resolve());
        }
      });
    });
    await Promise.all(promises);
  }

  checkAndStartGame() {
    // Count expected clients (all players except the host)
    const expectedClientCount = this.playerCount - 1;
    
    console.log(`Ready check: ${this.readyClients.size}/${expectedClientCount} clients ready`);
    
    // Only start if all non-host players are ready
    if (this.readyClients.size === expectedClientCount) {
      console.log("All clients ready, starting game!");
      this.broadcastStartGame();
    }
  }

  broadcastStartGame() {
    // Tell all clients to start the game
    this.connections.forEach((conn) => {
      conn.send({
        type: "start-game",
        roomId: this.matchmaker.clientID!,
      });
    });

    // Start the game locally too
    this.startGame(this.matchmaker.clientID!);
  }

  startGame(roomId: string) {
    // Build ordered player list
    const allPlayerIDs = [this.matchmaker.clientID!];
    this.connections.forEach((_, peerID) => {
      allPlayerIDs.push(peerID);
    });

    // Sort player IDs to ensure consistent ordering across all clients
    allPlayerIDs.sort();

    // Create NetplayPlayer objects
    const players: NetplayPlayer[] = allPlayerIDs.map((id) => {
      if (id === this.matchmaker.clientID!) {
        return { id, isLocal: true };
      } else {
        return { id, isLocal: false, conn: this.connections.get(id)! };
      }
    });

    // Emit the game start event
    this.onGameStart.emit({ players, roomId });

    this.updateState({
      kind: "game-in-progress",
    });

    // Set up connection close handlers
    this.connections.forEach((conn) => {
      conn.onClose.on(() => {
        this.updateState({
          kind: "connection-closed",
        });
      });
    });
  }

  startMatchmaking() {
    // Stop listening for connections.
    this.stopHostListening();
    
    // Reset ready clients
    this.readyClients.clear();

    // Send the match request and update UI to put
    // as in the matchmaking state.
    this.matchmaker.sendMatchRequest(
      this.gameURL,
      this.playerCount,
      this.playerCount
    );
    this.updateState({
      kind: "searching-for-matches",
      playerCount: this.playerCount,
    });

    this.matchmaker.onHostMatch.once((e) => {
      this.updateState({
        kind: "hosting-public-match",
        playerCount: this.playerCount,
        players: [
          { id: this.matchmaker.clientID!, isLocal: true },
          ...e.clientIDs.map(
            (id): PendingRemotePlayer => ({ id, isLocal: false })
          ),
        ],
      });
      this.startHostListening();
    });

    this.matchmaker.onJoinMatch.once((e) => {
      this.connectToPeers(e.hostID, this.playerCount);
    });
  }

  updateState(newState: GameMenuState) {
    this.state = newState;
    this.render();
  }

  /**
   * Try to get a server override from local storage.
   * Return NULL if we error (for example in incognito mode).
   */
  getLocalStorageServerOverride(): string | null {
    try {
      return window.localStorage.getItem("NETPLAYJS_SERVER_OVERRIDE");
    } catch {
      return null;
    }
  }

  getJoinURL(room: string, playerCount: number): string {
    let hashParams: { room: string; players: string; server?: string } = {
      room: room,
      players: playerCount.toString(),
    };
    if (this.matchmaker.serverURL !== DEFAULT_SERVER_URL) {
      hashParams.server = this.matchmaker.serverURL;
    }
    return `${this.gameURL}#${query.stringify(hashParams)}`;
  }

  centeredText(text: string) {
    return html`<div
      style="display: flex; width: 100%; height: 100%; align-items: center; justify-content: center;"
    >
      <div style="font-size: 1.5em;">${text}</div>
    </div>`;
  }

  menuContent() {
    if (this.state.kind === "connecting-to-server") {
      return this.centeredText("Connecting to NetplayJS server...");
    } else if (this.state.kind === "player-count-selection") {
      return html`<div
        style="display: flex; flex-direction: column; align-items: center; justify-content: center; width: 100%; height: 100%;"
      >
        <h1 style="margin: 20px;">Select Number of Players</h1>
        <div style="display: flex; gap: 20px;">
          ${[2, 3, 4, 5, 6].map(
            (count) => html`
              <button
                style="font-size: 2em; background-color: #4CAF50; color: white; padding: 20px 30px; border: none; cursor: pointer; border-radius: 5px;"
                @click=${() => this.selectPlayerCount(count)}
              >
                ${count}
              </button>
            `
          )}
        </div>
      </div>`;
    } else if (this.state.kind === "registered") {
      const connectedPlayers = this.state.players.filter(
        (p) => p.isLocal === true || (p as RemotePlayer).conn !== undefined
      );
      return html` <div
        style="display: grid; width: 100%; height: 100%; grid-template-columns: 1fr 1px 1fr; grid-column-gap: 10px;"
      >
        <div
          style="display: flex; flex-direction: column; align-items: center;"
        >
          <h1 style="margin: 5px;">Public Match</h1>
          <p>Play with random strangers on the internet.</p>
          <p style="font-size: 1.2em;">Players: ${this.state.playerCount}</p>
          <button
            style="font-size: 1.5em; background-color: #4CAF50; color: white; padding: 0.5em; border: none; cursor: pointer;"
            @click=${() => this.startMatchmaking()}
          >
            Start Matchmaking
          </button>
        </div>
        <div
          style="display: flex; width: 100%; height: 100%; align-items: center; justify-content: center;"
        >
          <div style="background-color: black; width: 1px; height: 75%;"></div>
        </div>

        <div
          style="display: flex; flex-direction: column; align-items: center;"
        >
          <h1 style="margin: 5px;">Private Match</h1>
          <p>Invite players to a game via a link or QR code.</p>
          <p style="font-size: 1.2em;">
            Players: ${connectedPlayers.length}/${this.state.playerCount}
          </p>
          <p>
            Connected:
            ${connectedPlayers
              .map((p) => String(p.id).substring(0, 8))
              .join(", ")}
          </p>
          Join URL (send this to a friend):

          <a target="_blank" href="${this.state.joinURL}">
            ${this.state.joinURL}
          </a>
          <div>${this.state.qrCanvas}</div>
        </div>
      </div>`;
    } else if (this.state.kind === "connecting-to-peers") {
      return this.centeredText(
        `Connecting to peers... (${this.state.playerCount} player game)`
      );
    } else if (this.state.kind === "searching-for-matches") {
      return this.centeredText(
        `Searching for matches... (${this.state.playerCount} players)`
      );
    } else if (this.state.kind === "hosting-public-match") {
      const connectedPlayers = this.state.players.filter(
        (p) => p.isLocal === true || (p as RemotePlayer).conn !== undefined
      );
      return this.centeredText(
        `You are the host. Waiting for players... (${connectedPlayers.length}/${this.state.playerCount})`
      );
    } else if (this.state.kind === "connection-closed") {
      return this.centeredText("The connection was closed...");
    }
  }

  render() {
    render(this.menuContent(), this.root);

    if (this.state.kind === "game-in-progress") {
      this.root.style.display = "none";
    } else {
      this.root.style.display = "inherit";
    }
  }

  createRootElement(): HTMLDivElement {
    // Create menu UI
    const menu = document.createElement("div");
    menu.style.zIndex = "1";
    menu.style.position = "absolute";
    menu.style.backgroundColor = "white";
    menu.style.padding = "10px";
    menu.style.left = "50%";
    menu.style.top = "50%";
    menu.style.boxShadow = "0px 0px 10px black";
    menu.style.transform = "translate(-50%, -50%)";

    menu.style.boxSizing = "border-box";
    menu.style.borderRadius = "5px";

    menu.style.width = "960px";
    menu.style.height = "400px";

    menu.style.maxWidth = "95%";
    menu.style.maxHeight = "95%";
    menu.style.fontFamily = "sans-serif";

    document.body.appendChild(menu);

    return menu;
  }

  destroy() {
    this.root.remove();
    this.matchmaker.destroy();
  }
}
